head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil16200";
scwin.candidateValSeq = undefined;
scwin.insQuest = undefined;
scwin.Quest = null;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — share, modulus, quesCnt, candidateValSeq

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "txa_ans", attr: "name", fn: function () { return "ans" + String(dma_ques.get("quesNo")); } },
        { childId: "txa_ans", attr: "label", fn: function () { return String(dma_ques.get("questAnsVal")); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_questComent", fn: function(){ return (!(String(((dma_ques.get("questComent") ?? (() => { throw new Error("unresolved:" + "ques.questComent"); })())) == null ? '' : ((dma_ques.get("questComent") ?? (() => { throw new Error("unresolved:" + "ques.questComent"); })()))).length === 0)); } }, { id: "c_when_42_txt", fn: function(){ return ((dma_ques.get("quesTpCd") ?? (() => { throw new Error("unresolved:" + "ques.quesTpCd"); })()) === '2'); } }, { id: "c_when_43_txt", fn: function(){ return ((dma_ques.get("quesTpCd") ?? (() => { throw new Error("unresolved:" + "ques.quesTpCd"); })()) === '3'); } }, { id: "c_when_44_txt", fn: function(){ return ((dma_ques.get("quesTpCd") ?? (() => { throw new Error("unresolved:" + "ques.quesTpCd"); })()) === '4'); } }, { id: "if_respnsMandtryNoContn_txt", fn: function(){ return (!(String(((dma_ques.get("respnsMandtryNoContn") ?? (() => { throw new Error("unresolved:" + "ques.respnsMandtryNoContn"); })())) == null ? '' : ((dma_ques.get("respnsMandtryNoContn") ?? (() => { throw new Error("unresolved:" + "ques.respnsMandtryNoContn"); })()))).length === 0)); } }, { id: "if_upQuesNo", fn: function(){ return ((dma_ques.get("upQuesNo") ?? (() => { throw new Error("unresolved:" + "ques.upQuesNo"); })()) !=='0'); } }, { id: "c_when_55", fn: function(){ return ((String((dma_ques.get("questAnsVal") ?? (() => { throw new Error("unresolved:" + "ques.questAnsVal"); })())).indexOf(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (scwin.candidateValSeq ?? ""))(dma_pageContext.get("candidateValSeq"))) !== -1)); } }, { id: "c_otherwise_57", fn: function(){ return (!(((String((dma_ques.get("questAnsVal") ?? (() => { throw new Error("unresolved:" + "ques.questAnsVal"); })())).indexOf(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (scwin.candidateValSeq ?? ""))(dma_pageContext.get("candidateValSeq"))) !== -1)))); } }, { id: "c_when_51", fn: function(){ return ((dma_ques.get("quesTpCd") ?? (() => { throw new Error("unresolved:" + "ques.quesTpCd"); })()) === '1'); } }, { id: "c_when_63", fn: function(){ return ((dma_ques.get("quesTpCd") ?? (() => { throw new Error("unresolved:" + "ques.quesTpCd"); })()) === '5'); } }, { id: "c_otherwise_67", fn: function(){ return (!(((dma_ques.get("quesTpCd") ?? (() => { throw new Error("unresolved:" + "ques.quesTpCd"); })()) === '1') || ((dma_ques.get("quesTpCd") ?? (() => { throw new Error("unresolved:" + "ques.quesTpCd"); })()) === '5'))); } }, { id: "c_when_72", fn: function(){ return ((String((dma_ques.get("questAnsVal") ?? (() => { throw new Error("unresolved:" + "ques.questAnsVal"); })())).indexOf(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (scwin.candidateValSeq ?? ""))(dma_pageContext.get("candidateValSeq"))) !== -1)); } }, { id: "c_otherwise_74", fn: function(){ return (!(((String((dma_ques.get("questAnsVal") ?? (() => { throw new Error("unresolved:" + "ques.questAnsVal"); })())).indexOf(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (scwin.candidateValSeq ?? ""))(dma_pageContext.get("candidateValSeq"))) !== -1)))); } }, { id: "btn_Prev", fn: function(){ return ((dma_pageContext.get("share") ?? "") !== 0); } }, { id: "c_when_83", fn: function(){ return ((dma_status.get("last") ?? (() => { throw new Error("unresolved:" + "status.last"); })())); } }, { id: "c_otherwise_92", fn: function(){ return (!(((dma_status.get("last") ?? (() => { throw new Error("unresolved:" + "status.last"); })())))); } }, { id: "btn_Prev_2", fn: function(){ return ((dma_pageContext.get("share") ?? "") !== 0); } }, { id: "if_modulus", fn: function(){ return ((dma_pageContext.get("modulus") ?? "")===9); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_52", entity: "dlt_quesPollQuesCandidateVO", countIds: [], cells: [{ childId: "__rc8", fn: function (v, i) { return " (" + String(v("quesCandidateValSeq")) + ") " + String(v("quesCandidateVal")); } }] },
        { genId: "c_foreach_69", entity: "dlt_quesPollQuesCandidateVO", countIds: [], cells: [{ childId: "__rc9", fn: function (v, i) { return " (" + String(v("quesCandidateValSeq")) + ") " + String(v("quesCandidateVal")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb1", fn: function () { return String(dma_poll.get("questStrtDd")) + " ~ " + String(dma_poll.get("questEndDd")); } },
        { childId: "__rb3", fn: function () { return " " + String(dma_ques.get("quesNo")) + ". " + String(dma_ques.get("quesContn")); } },
        { childId: "__rb4", fn: function () { return "[택 " + String(dma_ques.get("ansChoicCnt")) + "개]"; } },
        { childId: "__rb5", fn: function () { return "[" + String(dma_ques.get("ansChoicCnt")) + "개까지 선택가능]"; } },
        { childId: "__rb6", fn: function () { return "(" + String(dma_ques.get("upQuesNo")) + "번 질문과 연관"; } },
        { childId: "__rb7", fn: function () { return "- 응답번호[" + String(dma_ques.get("respnsMandtryNoContn")) + "]시"; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.initValue();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16200.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_Submit();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.insQuest =new Quest((String(((dma_pageContext.get("quesCnt") ?? "")) == null ? '' : ((dma_pageContext.get("quesCnt") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("quesCnt") ?? "")) == null ? '' : ((dma_pageContext.get("quesCnt") ?? ""))))); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil16200' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.Quest = Quest;
        scwin.init_fillGen();
        scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil16200.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
