scwin.ipt_ans_onclick = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.chekRadioAns('' + dma_ques.get("quesNo") + '',selfVar)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16200.ipt_ans_onclick' }); }
};

