scwin.btn_Prev_2_onclick = function(e){
    try {
        scwin.prev((String(((dma_pageContext.get("share") ?? "")) == null ? '' : ((dma_pageContext.get("share") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("share") ?? "")) == null ? '' : ((dma_pageContext.get("share") ?? "")))))

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16200.btn_Prev_2_onclick' }); }
