 */
scwin.btn_Next_onclick = function(e){
    try {
        scwin.next((String(((dma_pageContext.get("share") ?? "")) == null ? '' : ((dma_pageContext.get("share") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("share") ?? "")) == null ? '' : ((dma_pageContext.get("share") ?? "")))))

