///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Submit
 * @description Submit 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Submit = async function (action) {
    const sbmOptions = {
        id: "tx_fn_Submit",
        method: "post",
        action: action ?? "/support/poll.do",
        ref: "dma_SubmitReq",
        target: "dlt_quesPollQuesCandidateVO=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
function Quest(_quesCnt) {
    this.quesCnt = _quesCnt;
    this.quesObj = [];
}

/**
 * @method
 * @name Ques
 * @description Ques 처리
 * @param {*} _quesNo _quesNo
 * @param {String} _quesTpCd _quesTpCd
 * @param {*} _ansChoicCnt _ansChoicCnt
 * @param {*} _upQuesNo _upQuesNo
 * @param {*} _respnsMandtryNoContn _respnsMandtryNoContn
 * @param {String} _respnsMandtryYn _respnsMandtryYn
 * @returns {void}
 * @hidden N
 */
scwin.Ques = function (_quesNo, _quesTpCd, _ansChoicCnt, _upQuesNo, _respnsMandtryNoContn, _respnsMandtryYn) {
    this.quesNo = _quesNo;
    this.quesTpCd = _quesTpCd;
    this.ansChoicCnt = _ansChoicCnt;
    this.upQuesNo = _upQuesNo;
    this.respnsMandtryNoContn = _respnsMandtryNoContn;
    this.respnsMandtryYn = _respnsMandtryYn;
};

/**
 * @method
 * @name prev
 * @description prev 처리
 * @param {*} _divNo _divNo
 * @returns {void}
 * @hidden N
 */
scwin.prev = function (_divNo) {
    const curObj = $c.util.getComponent("pollDiv" + _divNo);
    const prevObj = $c.util.getComponent("pollDiv" + (_divNo - 1));
    curObj.style.display = 'none';
    prevObj.style.display = 'inline';
};

/**
 * @method
 * @name next
 * @description next 처리
 * @param {*} _divNo _divNo
 * @returns {void}
 * @hidden N
 */
scwin.next = function (_divNo) {
    const curObj = $c.util.getComponent("pollDiv" + _divNo);
    const nextObj = $c.util.getComponent("pollDiv" + (_divNo + 1));
    curObj.style.display = 'none';
    nextObj.style.display = 'inline';
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function () {
    $c.util.getComponent('dma_SubmitReq').set('questProgStatCd', '1');
    scwin.presetValue();
    await scwin.submit();
};

/**
 * @method
 * @name confirm
 * @description confirm 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.confirm = async function () {
    $c.util.getComponent('dma_SubmitReq').set('questProgStatCd', '2');
    scwin.presetValue();
    if (!await scwin.checkForm()) {
        return;
    }
    await scwin.submit();
};

