 */
scwin.presetValue = function () {
    const frm = (document.pollForm || { elements: [] });
    for (let i = 0; i < scwin.insQuest.quesObj.length; i++) {
        const insQues = scwin.insQuest.quesObj[i];
        const quesTpCd = insQues.quesTpCd;
        switch (Number(quesTpCd)) {
            case 2:

            case 3:

            case 4:
            const ansObj = frm['ans' + insQues.quesNo];
            const ansCheckboxObj = frm['ansMulti' + insQues.quesNo];
            const checkedVal = scwin.getMultiCheckedValue(ansCheckboxObj);
            ansObj.value = checkedVal;
            break;
        }
    }
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function () {
    let isVallid = true;
    for (let i = 0; i < scwin.insQuest.quesObj.length; i++) {
        const insQues = scwin.insQuest.quesObj[i];
        const quesTpCd = insQues.quesTpCd;
        if (insQues.respnsMandtryYn === 'N') {
            switch (Number(quesTpCd)) {
                case 1:
                continue;
                case 2:
                let frm = (document.pollForm || { elements: [] });
                let ansVal = $c.util.getComponent('frm.' + 'ans' + insQues.quesNo).getValue();
                if (ansVal === '') {
                    continue;
                }
                break;
                case 3:
                frm = (document.pollForm || { elements: [] });
                ansVal = $c.util.getComponent('frm.' + 'ans' + insQues.quesNo).getValue();
                if (ansVal === '') {
                    continue;
                }
                break;
                case 4:
                continue;
                case 5:
                continue;
            }
        }
        switch (Number(quesTpCd)) {
            case 1:
            isVallid = await scwin.radioChk(insQues);
            break;
            case 2:
            isVallid = await scwin.checkboxChk1(insQues);
            break;
            case 3:
            isVallid = await scwin.checkboxChk2(insQues);
            break;
            case 4:
            isVallid = await scwin.checkboxChk3(insQues);
            break;
            case 5:
            isVallid = await scwin.textareaChk(insQues);
            break;
        }
        if (!isVallid) {
            break;
        }
    }
    return isVallid;
};

/**
 * @method
 * @name radioChk
 * @description radio Chk 처리
 * @param {*} _insQues _insQues
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.radioChk = async function (_insQues) {
    let chkPassed = true;
    let hasCheck = true;
    const upQuesNo = _insQues.upQuesNo;
    if (upQuesNo !== 0) {
        const upQues = scwin.insQuest.quesObj[Number(upQuesNo)-1];
        const upOuesTpCd = upQues.quesTpCd;
        const respnsMandtryNoContn = _insQues.respnsMandtryNoContn;
        hasCheck = scwin.upQuesChk(upQuesNo, upOuesTpCd, respnsMandtryNoContn);
    }
    if (hasCheck) {
        const frm = (document.pollForm || { elements: [] });
        const ansObj = frm['ans' + _insQues.quesNo];
        if (scwin.isChecked(ansObj)) {
            chkPassed = true;
        } else {
            await $c.win.alert(_insQues.quesNo + '번 질문의 답이 없습니다.');
            chkPassed = false;
        }
    }
    return chkPassed;
};

