/**
 * @method
 * @name upQuesChk
 * @description up Ques Chk 처리
 * @param {*} upQuesNo upQuesNo
 * @param {String} upOuesTpCd upOuesTpCd
 * @param {*} respnsMandtryNoContn respnsMandtryNoContn
 * @returns {void}
 * @hidden N
 */
scwin.upQuesChk = function (upQuesNo, upOuesTpCd, respnsMandtryNoContn) {
    const frm = (document.pollForm || { elements: [] });
    const upAnsObj = frm['ans' + upQuesNo];
    switch (Number(upOuesTpCd)) {
        case 1:
        let upAnsVal = scwin.getCheckedValue(upAnsObj);
        if (respnsMandtryNoContn === upAnsVal) {
            return true;
        } else {
            return false;
        }
        break;
        case 2:

        case 3:

        case 4:
        upAnsVal = upAnsObj.value;
        if (scwin.ansContains(upAnsVal, respnsMandtryNoContn)) {
            return true;
        } else {
            return false;
        }
        break;
        case 5:
        upAnsVal = upAnsObj.value;
        if (upAnsVal !== '') {
            return true;
        } else {
            return false;
        }
        break;
    }
    return false;
};

/**
 * @method
 * @name ansContains
 * @description ans Contains 처리
 * @param {*} _upAnsVal _upAnsVal
 * @param {*} _respnsMandtryNoContn _respnsMandtryNoContn
 * @returns {void}
 * @hidden N
 */
scwin.ansContains = function (_upAnsVal, _respnsMandtryNoContn) {
    let isContains = false;
    if (_respnsMandtryNoContn !== '') {
        const respnsMandtryNoContn = _respnsMandtryNoContn.split(',');
        for (let i = 0; i < respnsMandtryNoContn.length; i++) {
            const resVal = respnsMandtryNoContn[i];
            if (_upAnsVal.indexOf(resVal) >= 0) {
                isContains = true;
                break;
            }
        }
    }
    return isContains;
};

