 */
scwin.initValue = function () {
    ($c.util.getComponent('pollDiv0') && $c.util.getComponent('pollDiv0').show ? $c.util.getComponent('pollDiv0').show() : console.warn('[sdd] show 대상 미해결: ' + 'pollDiv0'));
};

/**
 * @method
 * @name chekRadioAns
 * @description chek Radio Ans 처리
 * @param {*} quesNo quesNo
 * @param {*} objparam2 objparam2
 * @returns {void}
 * @hidden N
 */
scwin.chekRadioAns = function (quesNo, objparam2) {
    const obj = document.getElementsByName(objparam2.name);
    for (let i = 0; i < obj.length; i++) {
        if (obj[i].checked) {
            const tmpAnsNo = i + 1;
            const strAnsNo = "0" + tmpAnsNo;
            for (let ii = 0; ii < scwin.insQuest.quesObj.length; ii++) {
                const insQues = scwin.insQuest.quesObj[ii];
                if (insQues.upQuesNo === quesNo) {
                    const relNo = "ans" + insQues.quesNo;
                    const relobj = document.getElementsByName(relNo);
                    if (insQues.respnsMandtryNoContn.indexOf(strAnsNo) > -1) {
                        for (let j = 0; j < relobj.length; j++) {
                            relobj[j].disabled = false;
                        }
                    } else {
                        for (let j = 0; j < relobj.length; j++) {
                            relobj[j].disabled = true;
                        }
                    }
                }
            }
        }
    }
};

/**
 * @method
 * @name getMultiCheckedValue
 * @description get Multi Checked Value 처리
 * @param {*} _obj _obj
 * @returns {void}
 * @hidden N
 */
scwin.getMultiCheckedValue = function (_obj) {

    let checkedValue = '';
    for(let i=0; i<_obj.length; i++){
        if(_obj[i].checked){
            if(checkedValue !== '') {
                checkedValue += ',';
            }
            checkedValue += _obj[i].value;
        }
    }
    return checkedValue;
};

/**
 * @method
 * @name isChecked
 * @description is Checked 처리
 * @param {*} _obj _obj
 * @returns {void}
 * @hidden N
 */
scwin.isChecked = function (_obj) {

    let isChecked = false;
    for(let i=0; i<_obj.length; i++){
        if(_obj[i].checked){
            isChecked = true;
            break;
        }
    }
    return isChecked;
};

/**
 * @method
 * @name trim
 * @description trim 처리
 * @param {*} _str _str
 * @returns {void}
 * @hidden N
 */
scwin.trim = function (_str) {

    if(typeof(_str)!=='undefined') return _str.replace(/^\s{1,}/, "").replace(/\s{1,}$/, "");
    else return _str;
};

/**
 * @method
 * @name getCheckedValue
 * @description get Checked Value 처리
 * @param {*} _obj _obj
 * @returns {void}
 * @hidden N
 */
scwin.getCheckedValue = function (_obj) {

    let checkedValue = '';
    for(let i=0; i<_obj.getItemCount(); i++){
        if(_obj[i].checked){
            checkedValue = _obj[i].value;
            break;
        }
    }
    return checkedValue;
};
